import Foundation
import Testing
@testable import XdeskClipboard
import XdeskWire

@Suite struct ClipboardItemTests {
    @Test func policyRefusesSensitiveTypes() {
        #expect(ClipboardPolicy.refusalReason(types: ["public.utf8-plain-text", "org.nspasteboard.ConcealedType"]) != nil)
        #expect(ClipboardPolicy.refusalReason(types: ["org.nspasteboard.TransientType"]) != nil)
        #expect(ClipboardPolicy.refusalReason(types: ["org.nspasteboard.AutoGeneratedType"]) != nil)
        #expect(ClipboardPolicy.refusalReason(types: ["public.utf8-plain-text"]) == nil)
    }

    @Test func rejectsEmptyOversizedAndMalformed() {
        #expect(ClipboardItem(kind: .text, data: []) == nil)
        #expect(ClipboardItem(kind: .text, data: [UInt8](repeating: 65, count: ClipLimits.maxBytes + 1)) == nil)
        #expect(ClipboardItem(kind: .text, data: [0xFF, 0xFE]) == nil)
        #expect(ClipboardItem(kind: .image, data: [1, 2, 3]) == nil)
        #expect(ClipboardItem(kind: .image, data: [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]) != nil)
        #expect(ClipboardItem(kind: .text, data: [UInt8](repeating: 65, count: ClipLimits.maxBytes)) != nil)
    }

    @Test func hashIsSha256Hex() {
        #expect(text("abc").hash == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
    }
}
